begin
 begin
 actor:=jsonb_build_object('id',scope||'_owner','username',scope,'fullName','Fraud accounting rollback QA','role','admin','isActive',true,'password',gen_random_uuid()::text,'permissions',jsonb_build_array('view','add','edit','delete','manage_finance'),'_erpTestScope',scope);
 insert into public.users(id,data) values(actor->>'id',actor-'password');uid:=erp_private.sync_identity(actor);update erp_private.members set test_scope=scope where auth_id=uid;
 insert into auth.sessions(id,user_id) values(sid,uid);perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true);

 seeds:=replace(seeds::text,'__FRAUD_SCOPE__',scope)::jsonb;
 requests:=replace(requests::text,'__FRAUD_SCOPE__',scope)::jsonb;
 for x in select value from jsonb_array_elements(seeds) loop
  if x->>'table'='system_kv' then insert into public.system_kv(key,value) values(scope||':'||(x->>'id'),x->'data');
  else execute format('insert into public.%I(id,data) values($1,$2)',x->>'table') using x->>'id',(x->'data')||jsonb_build_object('_erpTestScope',scope);end if;
 end loop;
 for x in select value from jsonb_array_elements(requests) loop
  if x->>'table'<>'system_kv' then
   if x->'before'<>'null'::jsonb then x:=jsonb_set(x,'{before}',(x->'before')||jsonb_build_object('_erpTestScope',scope));end if;
   if x->'after'<>'null'::jsonb then x:=jsonb_set(x,'{after}',(x->'after')||jsonb_build_object('_erpTestScope',scope));end if;
  end if;
  payload:=payload||jsonb_build_array(x);
 end loop;
 -- Old client: no accounting protocol => reject, and do not write anything.
 select jsonb_agg(case when x->>'table'='tickets' then jsonb_set(x,'{after,fraudDetails,accountingVersion}','0') else x end) into bad from jsonb_array_elements(payload)x;
 blocked:=false;begin perform public.erp_commit_changes(gen_random_uuid(),bad);exception when sqlstate 'PT409' then blocked:=true;end;if not blocked then raise exception 'old_fraud_client_accepted';end if;
 -- A hidden second deduction/restore of inventory is forbidden.
 bad:=payload||jsonb_build_array(jsonb_build_object('table','system_kv','id','jkr_wallets_v2','exists',true,'before',(select value from public.system_kv where key=scope||':jkr_wallets_v2'),'after','[]'::jsonb));
 blocked:=false;begin perform public.erp_commit_changes(gen_random_uuid(),bad);exception when sqlstate 'PT409' then blocked:=true;end;if not blocked then raise exception 'fraud_inventory_mutated';end if;
 -- Missing receipt reversal or reward exclusion => reject the entire batch.
 select jsonb_agg(x) into bad from jsonb_array_elements(payload)x where not(x->>'table'='store_wallet_transactions' and x#>>'{after,sourceType}'='fraud');
 blocked:=false;begin perform public.erp_commit_changes(gen_random_uuid(),bad);exception when others then if sqlerrm not like '%سجل إلغاء%' then raise;end if;blocked:=true;end;if not blocked then raise exception 'missing_fraud_journal_accepted';end if;
 select jsonb_agg(x) into bad from jsonb_array_elements(payload)x where not(x->>'table'='system_kv' and x->>'id' in ('cashback','nzm_jkr_cashback'));
 blocked:=false;begin perform public.erp_commit_changes(gen_random_uuid(),bad);exception when sqlstate 'PT409' then blocked:=true;end;if not blocked then raise exception 'fraud_rewards_not_reversed';end if;
 result:=public.erp_commit_changes(op,payload);
 if (select data->>'status' from public.tickets where id=scope||':JKR-2026-3107')<>'fraud' then raise exception 'fraud_not_saved';end if;
 if (select data#>>'{numbers,0,currentBalance}' from public.store_wallets where id=scope||':cash')<>'1000' then raise exception 'fraud_cash_not_reversed';end if;
 if (select value#>>'{0,pointsBalance}' from public.system_kv where key=scope||':jkr_wallets_v2')<>'102.46' then raise exception 'fraud_goods_changed';end if;
 if public.erp_commit_changes(op,payload)<>result then raise exception 'fraud_not_idempotent';end if;
 blocked:=false;begin perform public.erp_commit_changes(gen_random_uuid(),payload);exception when sqlstate 'PT409' then blocked:=true;end;if not blocked then raise exception 'stale_fraud_accepted';end if;
 raise exception using errcode='ZX001',message='fraud_rpc_checks_passed';
 exception when sqlstate 'ZX001' then null;end;
end $qa$;
select 'PASS: scoped fraud RPC, cash and rewards reversed, goods unchanged, old client/journal/rewards/inventory rejected, retry idempotent, stale writes rejected; fixtures rolled back' verification;
